"use client";

import { useEffect, useMemo, useState, type CSSProperties, type MouseEvent as ReactMouseEvent, type ReactNode } from "react";
import { usePathname, useRouter } from "next/navigation";
import emailStarterStyles from "./email-starter.module.css";
import emailEditorStyles from "./email-editor.module.css";
import {
  Activity, Bell, Bot, Box, CalendarDays, ChevronDown, ChevronLeft, ChevronRight,
  CircleHelp, Code2, Copy, Database, FileCode2, Flag, Filter, Grid2X2, Image,
  LayoutDashboard, LineChart, Mail, MapPin, MessageCircle, MoreHorizontal,
  MousePointerClick, Plus, Search, Send, Settings, ShieldCheck, Smartphone,
  Sparkles, Tags, Users, Webhook, X, Zap
} from "lucide-react";

type Channel = "email" | "push" | "iam" | "content" | "banner" | "sms" | "webhook" | "whatsapp" | "line" | "multichannel" | "operator" | "feature" | "api";
type CampaignStatus = "Draft" | "Active" | "Stopped";
type Campaign = { id: string; name: string; channel: Channel; status: CampaignStatus; schedule: string; sent: number; edited: string; subject?: string; body?: string; audience?: string; conversion?: string };
type EmailEditorMode = "operator" | "drag" | "html" | "template";

const nav = [
  { group: "Quick links", items: [["Canvas", "canvas", Grid2X2], ["Campaigns", "campaigns", LayoutDashboard], ["Segments", "segments", Users]] },
  { group: "", items: [["Getting Started", "getting-started", Flag], ["Performance Overview", "performance", LineChart], ["Agent Console", "agents", Bot], ["Messaging", "messaging", MessageCircle], ["Audience", "audience", Users], ["Content", "content", Box], ["Analytics", "analytics", LineChart], ["Partner Integrations", "partners", Zap], ["Data Settings", "data", Database], ["Settings", "settings", Settings]] }
] as const;

const drawers: Record<string, string[]> = {
  messaging: ["Canvas", "Campaigns", "Feature Flags", "Landing Pages", "Surveys", "Banners", "Content Calendar", "Messaging Diagnostics"],
  audience: ["Segments", "Segment Extensions", "Global Control Group", "Suppression Lists", "Subscription Group Management", "Email Preference Centers", "Search Users", "Manage Audience", "Import Users", "Locations"],
  content: ["Media Library", "Banner Templates", "Canvas Templates", "Content Blocks", "Email Link Templates", "Email Templates", "In-App Message Templates", "Webhook Templates", "Content Calendar", "Promotion Codes", "Catalogs", "Brand Guidelines"],
  analytics: ["Report Builder", "Custom Events Report", "Global Control Group Report", "Query Builder", "Engagement Reports", "Revenue Report", "Segment Insights", "Dashboard Builder", "Email Performance", "Push Performance", "SMS/MMS/RCS Performance", "Conversions"],
  partners: ["Technology Partners", "Currents", "Data Sharing", "Solutions Partners"],
  data: ["Custom Attributes", "Custom Events", "Catalogs", "Import Users", "Promotion Codes", "Products", "Cloud Data Ingestion", "Data Transformation"],
  settings: ["App Settings", "APIs and Identifiers", "Message Activity Log", "Event User Log", "Internal Groups", "Exports Log", "Tag Management", "Email Preferences", "Frequency Capping Rules", "Push Settings", "Approval Workflow", "Localization Settings", "Banner Placements", "Brand Guidelines", "Messaging Rate Limits", "Billing", "User Management"],
  agents: ["Canvas Step Agents", "Data Agents", "Catalog Agents"]
};

const channelMeta: Record<Channel, { title: string; icon: typeof Mail; description: string }> = {
  operator: { title: "Create with Operator", icon: Sparkles, description: "Describe a goal and create a coordinated draft." },
  multichannel: { title: "Multichannel", icon: Grid2X2, description: "Coordinate messages across one or more channels." },
  email: { title: "Email", icon: Mail, description: "Design a personalized email message." },
  push: { title: "Push notification", icon: Bell, description: "Send mobile and web notifications." },
  iam: { title: "In-app message", icon: Smartphone, description: "Reach users while they are active." },
  content: { title: "Content Card", icon: Box, description: "Deliver durable content in an app feed." },
  banner: { title: "Banner", icon: LayoutDashboard, description: "Place persistent messages on your property." },
  sms: { title: "SMS/MMS/RCS", icon: MessageCircle, description: "Send messaging through a subscriber group." },
  webhook: { title: "Webhook", icon: Webhook, description: "Call an external service with campaign data." },
  whatsapp: { title: "WhatsApp", icon: MessageCircle, description: "Send an approved WhatsApp template." },
  line: { title: "LINE", icon: MessageCircle, description: "Send a message through LINE Official Account." },
  feature: { title: "Feature flag experiment", icon: Flag, description: "Roll out a remote feature setting." },
  api: { title: "API campaign", icon: Code2, description: "Track messages sent from an API." }
};

const seed: Campaign[] = [
  { id: "cmp_3d084f2b", name: "New Campaign - September 16, 2026", channel: "email", status: "Draft", schedule: "One time", sent: 0, edited: "Sep 16, 2026", subject: "Your September Offer | 20% Off", body: "Thanks for being with us. Use code SEPTEMBER20 to get 20% off.", audience: "All Users", conversion: "Make Purchase" },
  { id: "cmp_newsletter", name: "Newsletter Welcome", channel: "email", status: "Active", schedule: "Action-based", sent: 18420, edited: "Sep 15, 2026", subject: "Welcome to Braze", body: "Your latest offers are waiting.", audience: "New Users", conversion: "Start Session" },
  { id: "cmp_push_primer", name: "Push Primer", channel: "push", status: "Active", schedule: "Action-based", sent: 9321, edited: "Sep 13, 2026", audience: "All Users", conversion: "Make Purchase" },
  { id: "cmp_banner", name: "Referral Banner", channel: "banner", status: "Draft", schedule: "One time", sent: 0, edited: "Sep 13, 2026", audience: "Recent Purchasers", conversion: "Make Purchase" },
  { id: "cmp_iam", name: "Welcome Offer IAM", channel: "iam", status: "Active", schedule: "Action-based", sent: 4784, edited: "Sep 13, 2026", audience: "New Users", conversion: "Start Session" }
];

const className = (...values: (string | false | undefined)[]) => values.filter(Boolean).join(" ");
const titleFrom = (value: string) => value.replace(/-/g, " ").replace(/\b\w/g, x => x.toUpperCase());

const routeForPage = (page: string) => {
  const routes: Record<string, string> = { campaigns: "/engagement/campaigns/campaigns?start=0&limit=12&sortby=last_edited&sortdir=-1&display=list", canvas: "/engagement/canvas", "getting-started": "/home", performance: "/analytics/performance-overview", agents: "/agent-console", messaging: "/messaging", audience: "/audience", content: "/content", analytics: "/analytics", partners: "/partner-integrations", data: "/data-settings", settings: "/settings", segments: "/audience/segments", "landing-pages": "/messaging/landing-pages", "search-users": "/audience/search-users", catalogs: "/content/catalogs", "content-calendar": "/messaging/content-calendar", "messaging-diagnostics": "/messaging/diagnostics" };
  return routes[page] ?? `/${page}`;
};

const pageFromPath = (pathname: string) => {
  if (pathname.includes("/engagement/campaigns")) return "campaigns";
  if (pathname.includes("canvas")) return "canvas";
  if (pathname === "/home") return "getting-started";
  const leaf = pathname.split("/").filter(Boolean).at(-1);
  return leaf || "campaigns";
};

export default function Dashboard() {
  const router = useRouter(); const pathname = usePathname();
  const [page, setPage] = useState("campaigns");
  const [drawer, setDrawer] = useState<string | null>(null);
  const [compact, setCompact] = useState(false);
  const [createAnchor, setCreateAnchor] = useState<CSSProperties | null>(null);
  const [campaigns, setCampaigns] = useState<Campaign[]>([]);
  const [editing, setEditing] = useState<Campaign | null>(null);
  const [toast, setToast] = useState("");
  const [operatorOpen, setOperatorOpen] = useState(false);

  const refreshCampaigns = async () => {
    const query = new URLSearchParams(window.location.search);
    const response = await fetch(`/api/campaigns?${new URLSearchParams({ limit: "100", q: query.get("globalFilter") ?? "", status: query.get("columnFilters[status]") ?? "All", sort: query.get("sortby") === "name" ? "name" : "edited" })}`);
    if (response.ok) { const result = await response.json(); setCampaigns(result.data); }
  };
  useEffect(() => { void refreshCampaigns(); }, []);
  useEffect(() => { setPage(pageFromPath(pathname)); }, [pathname]);
  useEffect(() => {
    const campaignId = pathname.match(/\/engagement\/campaigns\/(cmp_[^/]+)$/)?.[1];
    if (!campaignId) return;
    const storedDraft = window.sessionStorage.getItem(`braze:draft:${campaignId}`);
    if (storedDraft) {
      try { setEditing(JSON.parse(storedDraft) as Campaign); } catch { window.sessionStorage.removeItem(`braze:draft:${campaignId}`); }
    }
    void fetch(`/api/campaigns/${campaignId}`).then(response => response.ok ? response.json() : null).then(record => {
      if (record) { setEditing(record); window.sessionStorage.removeItem(`braze:draft:${campaignId}`); }
      else if (!storedDraft) { setEditing(null); setToast("Campaign draft could not be found."); }
    });
  }, [pathname]);
  useEffect(() => { if (!toast) return; const id = window.setTimeout(() => setToast(""), 2800); return () => window.clearTimeout(id); }, [toast]);

  function openPage(key: string) {
    setCreateAnchor(null); setDrawer(null); setEditing(null); setPage(key); router.push(routeForPage(key));
  }
  async function start(channel: Channel) {
    const id = `cmp_${Math.random().toString(36).slice(2, 10)}`;
    const item: Campaign = { id, name: `Untitled ${channelMeta[channel].title} Campaign`, channel, status: "Draft", schedule: "One time", sent: 0, edited: "Just now", audience: "All Users", conversion: "Make Purchase" };
    setCreateAnchor(null); setDrawer(null);
    window.sessionStorage.setItem(`braze:draft:${id}`, JSON.stringify(item));
    const response = await fetch("/api/campaigns", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(item) });
    if (!response.ok) { setEditing(item); setToast("Draft is open, but could not be saved yet."); return; }
    const saved = await response.json() as Campaign;
    setCampaigns(current => [saved, ...current.filter(campaign => campaign.id !== saved.id)]);
    setEditing(saved);
    router.push(`/engagement/campaigns/${id}?step=compose`);
  }
  async function saveCampaign(next: Campaign, publish = false) {
    const savedResponse = await fetch("/api/campaigns", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(next) });
    if (!savedResponse.ok) { setToast("Unable to save campaign."); return; }
    const saved = await savedResponse.json() as Campaign;
    if (publish) {
      const launched = await fetch(`/api/campaigns/${saved.id}/launch`, { method: "POST" });
      if (!launched.ok) { setToast("Campaign saved, but launch validation failed."); return; }
      const result = await launched.json(); setEditing(result.campaign); setToast(`Campaign launched for ${result.run.delivered.toLocaleString()} reachable users.`);
    } else { setEditing(saved); setToast("Changes were saved to local SQLite."); }
    await refreshCampaigns();
  }
  async function stopCampaign(id: string) {
    const response = await fetch(`/api/campaigns/${id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ status: "Stopped" }) });
    if (response.ok) { await refreshCampaigns(); setToast("Campaign stopped."); }
  }
  function openCampaign(campaign: Campaign) { setEditing(campaign); router.push(`/engagement/campaigns/${campaign.id}?step=compose`); }

  return <div className={className("app-shell", compact && "compact")}> 
    <aside className="sidebar">
      <div className="brand-mark">b</div>
      <button className="workspace" onClick={() => setCompact(!compact)}><ChevronLeft size={16}/><span>Demo – Thinkingai</span></button>
      {nav.map(section => <div className="nav-section" key={section.group}>
        {section.group && <span className="nav-caption">{section.group}</span>}
        {section.items.map(([label, key, Icon]) => <button key={key} className={className("nav-item", (page === key || drawer === key) && "active")} onClick={() => key in drawers ? setDrawer(drawer === key ? null : key) : openPage(key)}><Icon size={17}/><span>{label}</span></button>)}
      </div>)}
      <div className="brand-word">braze</div>
    </aside>
    <main className="main-area">
      <div className="trial">◷ &nbsp;12 days left in your free trial. <button>Connect with sales</button></div>
      <header className="topbar"><button className="search-button" onClick={() => setToast("Workspace search is ready for this local demo.")}><Search size={16}/> Search workspace <kbd>⌘K</kbd></button><div className="top-actions"><CircleHelp size={18}/><Bell size={18}/><button className="profile">S</button><button className="operator-trigger" onClick={() => setOperatorOpen(!operatorOpen)}><Sparkles size={17}/></button></div></header>
      <div className="page-tabs"><button className={className("page-tab", !editing && "selected")} onClick={() => { setEditing(null); setPage("campaigns"); }}>Campaigns</button>{editing && <button className="page-tab selected">Edit '{editing.name}' <X size={14} onClick={() => setEditing(null)}/></button>}</div>
      {editing ? <CampaignEditor campaign={editing} onSave={saveCampaign} onClose={() => openPage("campaigns")} /> : <PageContent page={page} campaigns={campaigns} openPage={openPage} onEdit={openCampaign} onCreate={(event) => { const rect = event.currentTarget.getBoundingClientRect(); setCreateAnchor({ position: "fixed", top: rect.bottom + 6, left: Math.max(16, rect.right - 325), zIndex: 61 }); }} onStop={stopCampaign} notify={setToast} />}
    </main>
    {drawer && <NavigationDrawer name={titleFrom(drawer)} items={drawers[drawer]} close={() => setDrawer(null)} open={(name) => { if (name === "Campaigns") openPage("campaigns"); else openPage(name.toLowerCase().replace(/\s+/g, "-")); }} />}
    {createAnchor && <CreateMenu anchor={createAnchor} start={start} close={() => setCreateAnchor(null)} />}
    {operatorOpen && <Operator close={() => setOperatorOpen(false)} start={start} />}
    {toast && <div className="toast"><ShieldCheck size={18}/><span>{toast}</span><button onClick={() => setToast("")}><X size={15}/></button></div>}
  </div>;
}

function NavigationDrawer({ name, items, close, open }: { name: string; items: string[]; close: () => void; open: (name: string) => void }) {
  return <div className="drawer-backdrop" onMouseDown={close}><section className="nav-drawer" onMouseDown={e => e.stopPropagation()}><header><h2>{name}</h2><button onClick={close}><X size={18}/></button></header><div className="drawer-list">{items.map((item, index) => <button key={item} onClick={() => open(item)}><span className="drawer-icon">{index % 3 === 0 ? <Grid2X2 size={18}/> : index % 3 === 1 ? <Activity size={18}/> : <Settings size={18}/>}</span><span><b>{item}</b><small>{drawerDescription(item)}</small></span><ChevronRight size={16}/></button>)}</div></section></div>;
}

function drawerDescription(name: string) {
  const descriptions: Record<string, string> = { "Content Calendar": "View upcoming scheduled campaigns and related analytics", "Messaging Diagnostics": "Troubleshoot why messages did not send", "Segments": "Split your audience into targeted groups", "Catalogs": "Manage non-user data such as products", "Report Builder": "Build and save performance reports", "Email Preferences": "Manage sending and subscription settings" };
  return descriptions[name] || `Manage ${name.toLowerCase()} for this workspace`;
}

function CreateMenu({ anchor, start, close }: { anchor: CSSProperties; start: (channel: Channel) => void; close: () => void }) {
  const standard: Channel[] = ["email", "push", "iam", "content", "banner", "sms", "webhook", "whatsapp", "line"];
  return <div className="create-popover-layer" style={{ position: "fixed", inset: 0, zIndex: 60 }} onMouseDown={close}><section className="create-menu" style={anchor} onMouseDown={e => e.stopPropagation()}><button className="create-option operator-option" onClick={() => start("operator")}><Sparkles size={17}/><span><b>Create with Operator</b><small>Generate a coordinated campaign draft</small></span></button><p>MESSAGE ONE OR MORE CHANNELS</p><button className="create-option" onClick={() => start("multichannel")}><Grid2X2 size={17}/><span><b>Multichannel</b><small>Coordinate messages across channels</small></span></button><p>SINGLE CHANNEL</p>{standard.map(channel => { const meta = channelMeta[channel]; const Icon = meta.icon; return <button className="create-option" key={channel} onClick={() => start(channel)}><Icon size={17}/><span><b>{meta.title}</b><small>{channel === "iam" ? "1 / 200 active" : channel === "content" ? "0 / 500 active" : channel === "banner" ? "0 / 200 active" : ""}</small></span></button>; })}<p>FEATURE FLAGS</p><button className="create-option" onClick={() => start("feature")}><Flag size={17}/><span><b>Feature flag experiment</b><small>0 / 1 active</small></span></button><p>TRACK MESSAGES SENT VIA API</p><button className="create-option" onClick={() => start("api")}><Code2 size={17}/><span><b>API campaign</b></span></button></section></div>;
}

function Operator({ close, start }: { close: () => void; start: (channel: Channel) => void }) {
  const [prompt, setPrompt] = useState("");
  return <aside className="operator"><header><h2><Sparkles size={16}/> BrazeAI Operator™</h2><button onClick={close}><X size={17}/></button></header><div className="operator-chat">What kind of campaign would you like to create?</div><div className="operator-chat">I can choose channels, draft copy, and configure targeting for a local campaign draft.</div><textarea value={prompt} onChange={e => setPrompt(e.target.value)} placeholder="Ask Operator to create a campaign…"/><button className="primary" style={{marginTop:10,width:"100%"}} onClick={() => { start("operator"); }}>Generate campaign plan</button></aside>;
}

function PageContent({ page, campaigns, openPage, onEdit, onCreate, onStop, notify }: { page: string; campaigns: Campaign[]; openPage: (p: string) => void; onEdit: (c: Campaign) => void; onCreate: (event: ReactMouseEvent<HTMLButtonElement>) => void; onStop: (id: string) => void; notify: (m: string) => void }) {
  if (page === "campaigns") return <CampaignList campaigns={campaigns} onEdit={onEdit} onCreate={onCreate} onStop={onStop}/>;
  if (page === "canvas") return <LiveCanvas notify={notify}/>;
  if (page === "getting-started") return <GettingStarted openPage={openPage}/>;
  if (page === "performance") return <Performance campaigns={campaigns}/>;
  if (page === "demo-lab") return <LiveDemoLab notify={notify}/>;
  if (["report-builder", "custom-events-report", "global-control-group-report", "query-builder", "engagement-reports", "revenue-report", "segment-insights", "dashboard-builder", "email-performance", "push-performance", "sms-mms-rcs-performance", "conversions"].includes(page)) return <LiveReportPage title={titleFrom(page)} />;
  if (page === "message-activity-log") return <ActivityLogPage />;
  if (page === "catalogs") return <CatalogWorkspace notify={notify}/>;
  return <ModuleWorkspace title={titleFrom(page)} page={page} notify={notify} openPage={openPage}/>;
}

function CampaignList({ campaigns, onEdit, onCreate, onStop }: { campaigns: Campaign[]; onEdit: (c: Campaign) => void; onCreate: (event: ReactMouseEvent<HTMLButtonElement>) => void; onStop: (id: string) => void }) {
  const [search, setSearch] = useState(""); const [status, setStatus] = useState("All"); const [sort, setSort] = useState<"name" | "edited">("edited");
  const filtered = useMemo(() => campaigns.filter(c => c.name.toLowerCase().includes(search.toLowerCase()) && (status === "All" || c.status === status)).sort((a,b) => sort === "name" ? a.name.localeCompare(b.name) : b.edited.localeCompare(a.edited)), [campaigns, search, status, sort]);
  return <section className="page-content"><div className="page-heading"><div><div className="title-line"><h1>Campaigns</h1><span className="access-pill">Limited access</span></div><p>Campaigns let you send a single, targeted message through email, push, SMS, and more, ensuring timely communication with your audience</p></div><div className="heading-actions"><button className="secondary">Send feedback</button><button className="secondary">Take a tour <ChevronDown size={14}/></button><button className="primary" onClick={onCreate}><Plus size={16}/> Create campaign <ChevronDown size={14}/></button></div></div><div className="filters"><label>Status<select value={status} onChange={e => setStatus(e.target.value)}><option>All</option><option>Draft</option><option>Active</option><option>Stopped</option></select></label><label>Tag<select><option>Select...</option><option>Lifecycle</option><option>Promotional</option></select></label><button className="secondary"><Filter size={15}/> Filters</button><button className="secondary"><Grid2X2 size={15}/> Columns</button><button className="text-button" onClick={() => { setStatus("All"); setSearch(""); }}>Reset filters</button><div className="filter-search"><Search size={15}/><input placeholder="Search" value={search} onChange={e => setSearch(e.target.value)}/></div></div><div className="result-heading"><span>{filtered.length} Results</span><small>{status !== "All" ? `Status: ${status}` : "All campaigns"}</small></div><div className="table-wrap"><table><thead><tr><th onClick={() => setSort("name")}>Name {sort === "name" && "↑"}</th><th>Status</th><th>Stop date</th><th>Campaign type</th><th>Entry schedule</th><th>Sent</th><th>Last edited</th><th></th></tr></thead><tbody>{filtered.map(c => { const Icon = channelMeta[c.channel].icon; return <tr key={c.id}><td><button className="link-button" onClick={() => onEdit(c)}>{c.name}</button></td><td><span className={className("status", c.status.toLowerCase())}>{c.status}</span></td><td>—</td><td><span className="channel-cell"><Icon size={14}/>{channelMeta[c.channel].title}</span></td><td>{c.schedule}</td><td>{c.sent.toLocaleString()}</td><td>{c.edited}</td><td><button className="icon-button" onClick={() => c.status === "Active" ? onStop(c.id) : onEdit(c)} title={c.status === "Active" ? "Stop campaign" : "Edit campaign"}><MoreHorizontal size={18}/></button></td></tr>; })}</tbody></table></div></section>;
}

function CampaignEditor({ campaign, onSave, onClose }: { campaign: Campaign; onSave: (c: Campaign, publish?: boolean) => void; onClose: () => void }) {
  const [draft, setDraft] = useState(campaign); const [step, setStep] = useState(0); const [variant, setVariant] = useState(0); const [testOpen, setTestOpen] = useState(false);
  const steps = ["Compose Messages", "Schedule Delivery", "Target Audiences", "Assign Conversions", "Review Summary"];
  const update = (patch: Partial<Campaign>) => setDraft(d => ({ ...d, ...patch }));
  const ChannelIcon = channelMeta[draft.channel].icon;
  return <section className="editor-page"><div className="editor-steps">{steps.map((item, i) => <button key={item} className={className("editor-step", step === i && "current", step > i && "complete")} onClick={() => setStep(i)}><span>{step > i ? "✓" : i + 1}</span>{item}</button>)}</div><div className="editor-title"><h1>{draft.name || `Untitled ${channelMeta[draft.channel].title} Campaign`}</h1><span><ChannelIcon size={14}/>{channelMeta[draft.channel].title}</span></div>{step === 0 && <Compose draft={draft} update={update} variant={variant} setVariant={setVariant} openTest={() => setTestOpen(true)}/>} {step === 1 && <Schedule draft={draft} update={update}/>} {step === 2 && <Audience draft={draft} update={update}/>} {step === 3 && <Conversions draft={draft} update={update}/>} {step === 4 && <Review draft={draft} go={setStep}/>}<footer className="editor-footer"><button className="secondary" disabled={step === 0} onClick={() => setStep(s => s - 1)}><ChevronLeft size={16}/> Back</button><span>All changes saved locally</span><button className="secondary" onClick={() => onSave(draft)}>Save Draft</button>{step === 4 ? <button className="primary" onClick={() => onSave(draft, true)}><Send size={15}/> Launch Campaign</button> : <button className="primary" onClick={() => setStep(s => s + 1)}>Next: {steps[step + 1]} <ChevronRight size={16}/></button>}</footer>{testOpen && <TestModal draft={draft} close={() => setTestOpen(false)}/>}<button className="close-editor" onClick={onClose}><X size={18}/> Close editor</button></section>;
}

function Compose({ draft, update, variant, setVariant, openTest }: { draft: Campaign; update: (p: Partial<Campaign>) => void; variant: number; setVariant: (x: number) => void; openTest: () => void }) {
  const channel = draft.channel;
  if (channel === "email") return <EmailCompose draft={draft} update={update} variant={variant} setVariant={setVariant} openTest={openTest}/>;
  return <ChannelCompose draft={draft} update={update} openTest={openTest}/>;
  const isEmail = channel === "multichannel" || channel === "operator";
  const isWebhook = channel === "webhook"; const isText = channel === "sms" || channel === "whatsapp" || channel === "line";
  return <div className="editor-body"><section className="editor-card"><h2>Campaign Details</h2><div className="form-grid"><Field label="Campaign Name"><input value={draft.name} onChange={e => update({ name: e.target.value })}/></Field><Field label="Teams"><select><option>Select teams...</option><option>Lifecycle Marketing</option><option>Growth</option></select></Field></div><Field label="Description"><textarea placeholder="Describe this campaign"/></Field><button className="tag-button"><Tags size={14}/> Tags</button></section><section className="editor-card"><div className="card-heading"><div><h2>{channelMeta[channel].title} Composer</h2><p>{channelMeta[channel].description}</p></div><button className="secondary" onClick={openTest}>Preview and test</button></div><div className="variant-row"><b>Variants</b><button className={className("variant", variant === 0 && "active")} onClick={() => setVariant(0)}>Variant 1</button><button className={className("variant", variant === 1 && "active")} onClick={() => setVariant(1)}>Variant 2</button><button className="add-variant" onClick={() => setVariant(1)}><Plus size={15}/></button></div><div className="composer-grid"><div className="composer-form">{isEmail && <><Field label="From"><select><option>Powered by Braze &lt;braze@mta-h466.bftmail.com&gt;</option></select></Field><Field label="Subject"><input value={draft.subject || "Your welcome offer is here"} onChange={e => update({ subject: e.target.value })}/></Field><Field label="Preheader"><input placeholder="Optional preheader text"/></Field><div className="segmented"><button className="selected">Drag-and-drop editor</button><button>HTML editor</button></div></>}{channel === "push" && <><div className="segmented"><button className="selected">iOS</button><button>Android</button><button>Web</button></div><Field label="Notification title"><input value={draft.subject || "Your welcome offer is here"} onChange={e => update({subject: e.target.value})}/></Field><Field label="Deep link"><input defaultValue="myapp://offers/welcome"/></Field></>}{(channel === "iam" || channel === "content" || channel === "banner") && <><Field label="Message title"><input value={draft.subject || "Welcome to the family"} onChange={e => update({subject: e.target.value})}/></Field><div className="segmented"><button className="selected">Modal</button><button>Slideup</button><button>Full</button></div><Field label="Call to action"><input defaultValue="Shop now"/></Field></>}{isText && <><Field label="Sender / subscription group"><select><option>Promotional messages</option><option>Transactional</option></select></Field><Field label="Message"><textarea value={draft.body || "Welcome to Braze! Use code WELCOME10 for 10% off."} onChange={e => update({body: e.target.value})}/></Field><small>{(draft.body || "").length || 58} characters · 1 segment</small></>}{isWebhook && <><div className="form-grid"><Field label="HTTP method"><select><option>POST</option><option>PUT</option><option>GET</option></select></Field><Field label="Authentication"><select><option>Bearer token</option><option>None</option></select></Field></div><Field label="Webhook URL"><input defaultValue="https://api.example.com/events"/></Field><Field label="Request body"><textarea defaultValue={'{\n  "user_id": "{{${user_id}}}",\n  "event": "campaign_sent"\n}'}/></Field></>}{(channel === "feature" || channel === "api" || channel === "operator") && <><Field label={channel === "operator" ? "Campaign goal" : "Configuration"}><textarea value={draft.body || "Welcome new users and encourage their first purchase."} onChange={e => update({body: e.target.value})}/></Field><div className="subtle-note">This local demo models the configuration and event flow without calling an external service.</div></>}{!isText && !isWebhook && channel !== "feature" && channel !== "api" && <Field label="Message"><textarea value={draft.body || "Thanks for being with us. Use code SEPTEMBER20 to get 20% off this month’s featured collection."} onChange={e => update({body: e.target.value})}/></Field>}</div><MessagePreview draft={draft}/></div></section></div>;
}

function EmailCompose({ draft, update, variant, setVariant, openTest }: { draft: Campaign; update: (p: Partial<Campaign>) => void; variant: number; setVariant: (x: number) => void; openTest: () => void }) {
  const [showSending, setShowSending] = useState(false);
  const [showEditor, setShowEditor] = useState(false);
  const [showTemplates, setShowTemplates] = useState(false);
  const [copied, setCopied] = useState(false);
  const [emailStart, setEmailStart] = useState(() => !draft.subject && !draft.body);
  const [emailEditor, setEmailEditor] = useState<EmailEditorMode | null>(null);
  const [html, setHtml] = useState(`<div style="max-width:600px;margin:0 auto;padding:32px;font-family:Arial,sans-serif"><h1>September Exclusive</h1><p>Hi {{\${first_name} | default: 'there'}},</p><h2>Your September offer is here</h2><p>Thanks for being with us. Use code <b>SEPTEMBER20</b> to get 20% off this month's featured collection.</p><a href="https://example.com/offers">Claim your offer</a></div>`);
  if (emailEditor) return <EmailMessageEditor mode={emailEditor} draft={draft} update={update} onClose={() => { setEmailEditor(null); setEmailStart(false); }} />;
  if (emailStart) return <EmailStart draft={draft} update={update} variant={variant} setVariant={setVariant} copied={copied} setCopied={setCopied} onStart={setEmailEditor} />;
  const subject = draft.subject || "{% if ${language} == 'zh' %}九月专属优惠｜立减 20%{% else %}Your September Offer | 20% Off{% endif %}";
  const preheader = "{% if ${language} == 'zh' %}优惠码 SEPTEMBER20，9 月 30 日前有效。{% else %}Use code SEPTEMBER20 before September 30.{% endif %}";
  return <div className="editor-body email-compose-page">
    <section className="braze-section campaign-details-section">
      <h2>Campaign Details</h2>
      <div className="campaign-name-line"><Field label="Campaign Name"><input value={draft.name} onChange={e => update({name:e.target.value})} placeholder="Enter Campaign Name"/></Field><button className="inline-link">Add description</button><button className="tag-button"><Tags size={14}/> Tags <ChevronDown size={13}/></button></div>
      <div className="campaign-id-line"><Field label="Campaign ID"><input value={draft.id} readOnly/></Field><button className="copy-id" onClick={() => { navigator.clipboard?.writeText(draft.id); setCopied(true); }}><Copy size={15}/>{copied ? "Copied" : "Copy"}</button></div>
    </section>
    <section className="braze-section email-composer-section">
      <h2>Email Composer</h2>
      <div className="variant-header"><h3>Variants</h3><div className="real-tabs"><button className={className(variant === 0 && "selected")} onClick={() => setVariant(0)}>Variant 1</button><button className={className(variant === 1 && "selected")} onClick={() => setVariant(1)}>Unnamed Variant</button><button className="plus-tab" onClick={() => setVariant(1)}><Plus size={16}/></button></div></div>
      <div className="sending-info"><div><h3>Sending info</h3><dl><div><dt>From:</dt><dd>Powered by Braze &lt;braze@mta-h466.bftmail.com&gt;</dd></div><div><dt>Subject:</dt><dd>{subject}</dd></div><div><dt>Preheader:</dt><dd>{preheader}</dd></div><div><dt>One-click list-unsubscribe:</dt><dd>Use workspace default</dd></div></dl></div><button className="secondary small" onClick={() => setShowSending(!showSending)}>Edit sending info</button></div>
      {showSending && <div className="sending-editor"><div className="form-grid"><Field label="From"><select><option>Powered by Braze &lt;braze@mta-h466.bftmail.com&gt;</option></select></Field><Field label="From display name"><input defaultValue="Powered by Braze"/></Field></div><Field label="Subject"><input value={subject} onChange={e => update({subject:e.target.value})}/></Field><Field label="Preheader"><input defaultValue={preheader}/></Field><Toggle title="One-click list-unsubscribe" help="Use the workspace default list-unsubscribe setting." checked/></div>}
      <div className="email-body-heading"><div><h3>Email body</h3><p>HTML Editor</p></div><button className="secondary" onClick={() => setShowEditor(!showEditor)}>Edit message</button></div>
      {showEditor && <div className="html-workbench"><div className="editor-toolbar"><button className="selected"><FileCode2 size={14}/> HTML</button><button>Preview</button><button>Personalization</button><button>Content blocks</button></div><textarea value={html} onChange={e => setHtml(e.target.value)} aria-label="Email HTML editor"/></div>}
      <div className="email-document"><div className="email-document-top">September Offer</div><article><p className="email-kicker">September Exclusive</p><p>{"{% if ${language} == 'zh' %}"}</p><p>你好，{"{{${first_name} | default: '朋友'}}"}！</p><h1>九月专属礼遇已上线</h1><p>感谢一路相伴。使用优惠码 <b>SEPTEMBER20</b>，即可享受本月精选商品 20% 优惠。</p><a>立即领取优惠</a><p>优惠截止至 2026 年 9 月 30 日，条款与条件适用。</p><p>{"{% else %}"}</p><p>Hi {"{{${first_name} | default: 'there'}}"},</p><h1>Your September offer is here</h1><p>{draft.body || "Thanks for being with us. Use code SEPTEMBER20 to get 20% off this month's featured collection."}</p><a>Claim your offer</a><p>Offer ends September 30, 2026. Terms and conditions apply.</p><p>{"{% endif %}"}</p><hr/><p className="email-footer">Don't want to receive these emails? <a>Unsubscribe</a></p></article></div>
      <div className="email-actions"><button className="secondary" onClick={() => setShowTemplates(!showTemplates)}>Choose New Template</button><button className="secondary" onClick={openTest}>Preview and test</button></div>
      {showTemplates && <div className="template-picker"><b>Choose a template</b><button onClick={() => { update({subject:"Welcome to Braze"}); setShowTemplates(false); }}>Welcome email <small>Drag-and-Drop Editor</small></button><button onClick={() => { update({subject:"Your September Offer | 20% Off"}); setShowTemplates(false); }}>September Offer <small>HTML Editor</small></button></div>}
    </section>
  </div>;
}

function EmailStart({ draft, update, variant, setVariant, copied, setCopied, onStart }: { draft: Campaign; update: (patch: Partial<Campaign>) => void; variant: number; setVariant: (variant: number) => void; copied: boolean; setCopied: (copied: boolean) => void; onStart: (choice: "operator" | "drag" | "html" | "template") => void }) {
  return <div className="editor-body email-compose-page">
    <section className="braze-section campaign-details-section">
      <h2>Campaign Details</h2>
      <div className="campaign-name-line"><Field label="Campaign Name"><input value={draft.name} onChange={event => update({ name: event.target.value })} placeholder="Enter Campaign Name"/></Field><button className="inline-link">Add description</button><button className="tag-button"><Tags size={14}/> Tags <ChevronDown size={13}/></button></div>
      <div className="campaign-id-line"><Field label="Campaign ID"><input value={draft.id} readOnly/></Field><button className="copy-id" onClick={() => { navigator.clipboard?.writeText(draft.id); setCopied(true); }}><Copy size={15}/>{copied ? "Copied" : "Copy"}</button></div>
    </section>
    <section className="braze-section email-composer-section">
      <h2>Email Composer</h2>
      <div className="variant-header"><h3>Variants</h3><div className="real-tabs"><button className={className(variant === 0 && "selected")} onClick={() => setVariant(0)}>Variant 1</button><button className={className(variant === 1 && "selected")} onClick={() => setVariant(1)}>Unnamed Variant</button><button className="plus-tab" onClick={() => setVariant(1)}><Plus size={16}/></button></div></div>
      <div className={emailStarterStyles.starter}>
        <h3>Create new email</h3><p>How would you like to start?</p>
        <div className={emailStarterStyles.options}>
          <button className={emailStarterStyles.option} onClick={() => onStart("operator")}><span className={emailStarterStyles.operatorIcon}><Sparkles size={18}/></span><b>Create with Operator</b><small>Generate a custom email</small></button>
          <button className={emailStarterStyles.option} onClick={() => onStart("drag")}><span><LayoutDashboard size={19}/></span><b>Drag-and-drop editor</b><small>Start from scratch</small></button>
          <button className={emailStarterStyles.option} onClick={() => onStart("html")}><span><Code2 size={20}/></span><b>HTML code editor</b><small>Start from scratch</small></button>
          <button className={emailStarterStyles.option} onClick={() => onStart("template")}><span><FileCode2 size={19}/></span><b>Templates</b><small>Choose a template</small></button>
        </div>
        <label className={emailStarterStyles.upload}>Upload file<input type="file" accept=".html,.htm" onChange={event => { if (event.target.files?.length) { update({ body: "Imported HTML email" }); onStart("html"); } }}/></label>
      </div>
    </section>
  </div>;
}

function EmailMessageEditor({ mode, draft, update, onClose }: { mode: EmailEditorMode; draft: Campaign; update: (patch: Partial<Campaign>) => void; onClose: () => void }) {
  const [subject, setSubject] = useState(draft.subject ?? "Your September offer is here");
  const [body, setBody] = useState(draft.body ?? "Thanks for being with us. Use code SEPTEMBER20 to get 20% off this month’s featured collection.");
  const [operatorPrompt, setOperatorPrompt] = useState("Create a warm welcome email with a first-purchase offer.");
  const labels: Record<EmailEditorMode, string> = { operator: "Create with Operator", drag: "Drag-and-drop editor", html: "HTML code editor", template: "Templates" };
  const applyTemplate = (nextSubject: string, nextBody: string) => { setSubject(nextSubject); setBody(nextBody); };
  const saveAndReturn = () => { update({ subject, body }); onClose(); };
  const addBlock = (name: string) => setBody(current => `${current}\n\n[${name} block]`);
  return <section className={emailEditorStyles.page} aria-label="Email editor">
    <header className={emailEditorStyles.header}>
      <button className={emailEditorStyles.back} onClick={saveAndReturn}><ChevronLeft size={17}/> Back to campaign</button>
      <div className={emailEditorStyles.title}><b>{labels[mode]}</b><small>{draft.name} · Variant 1</small></div>
      <div className={emailEditorStyles.headerActions}><button className={emailEditorStyles.previewButton}><Smartphone size={15}/> Preview</button><button className={emailEditorStyles.saveButton} onClick={saveAndReturn}><Send size={14}/> Save</button></div>
    </header>
    <div className={emailEditorStyles.workspace}>
      <aside className={emailEditorStyles.sidebar}>
        {mode === "drag" && <><h2>Content</h2><p>Drag blocks onto the email canvas to build your message.</p><div className={emailEditorStyles.blockList}><button className={emailEditorStyles.block} onClick={() => addBlock("Text")}><FileCode2 size={16}/>Text</button><button className={emailEditorStyles.block} onClick={() => addBlock("Image")}><Image size={16}/>Image</button><button className={emailEditorStyles.block} onClick={() => addBlock("Button")}><MousePointerClick size={16}/>Button</button><button className={emailEditorStyles.block} onClick={() => addBlock("Divider")}><LayoutDashboard size={16}/>Divider</button></div></>}
        {mode === "html" && <><h2>HTML code</h2><p>Edit your email source. The central canvas renders its current message content.</p><textarea className={emailEditorStyles.codeArea} value={body} onChange={event => setBody(event.target.value)} aria-label="Email HTML source"/></>}
        {mode === "template" && <><h2>Templates</h2><p>Choose a template, then make changes in the settings panel.</p><div className={emailEditorStyles.templateList}><button className={`${emailEditorStyles.template} ${emailEditorStyles.templateActive}`} onClick={() => applyTemplate("Your September Offer | 20% Off", "Thanks for being with us. Use code SEPTEMBER20 to get 20% off this month’s featured collection.")}><b>September Offer</b><small>HTML Editor</small></button><button className={emailEditorStyles.template} onClick={() => applyTemplate("Welcome to Braze", "We’re glad you’re here. Explore the latest ways to make every customer interaction count.")}><b>Welcome email</b><small>Drag-and-drop Editor</small></button></div></>}
        {mode === "operator" && <><h2>Operator</h2><p>Describe the email you want to create.</p><textarea className={emailEditorStyles.operatorPrompt} value={operatorPrompt} onChange={event => setOperatorPrompt(event.target.value)}/><button className={emailEditorStyles.generate} onClick={() => applyTemplate("Your first order offer", "Welcome! Use code WELCOME10 for 10% off your first purchase. This offer is ready whenever you are.")}><Sparkles size={14}/> Generate email</button></>}
      </aside>
      <main className={emailEditorStyles.canvas}>
        <div className={emailEditorStyles.canvasLabel}>Email preview · 600 px</div>
        <article className={emailEditorStyles.emailFrame}>
          <div className={emailEditorStyles.brandLine}>BRAZE</div>
          <div className={emailEditorStyles.message}><p className={emailEditorStyles.eyebrow}>September exclusive</p><h1>{subject}</h1><p>{"Hi {{${first_name} | default: 'there'}}"},</p><p>{body}</p><span className={emailEditorStyles.cta}>Claim your offer</span><p className={emailEditorStyles.footer}>You are receiving this email because you subscribed to updates. Unsubscribe</p></div>
        </article>
      </main>
      <aside className={emailEditorStyles.settings}>
        <h2>Message settings</h2><label className={emailEditorStyles.field}><span>Subject line</span><input value={subject} onChange={event => setSubject(event.target.value)}/></label><label className={emailEditorStyles.field}><span>Preheader</span><input defaultValue="Use code SEPTEMBER20 before September 30."/></label><label className={emailEditorStyles.field}><span>Message</span><textarea value={body} onChange={event => setBody(event.target.value)}/></label><div className={emailEditorStyles.note}>Personalization, content blocks, and link tracking are available in this local editor.</div>
      </aside>
    </div>
  </section>;
}

function ChannelCompose({ draft, update, openTest }: { draft: Campaign; update: (patch: Partial<Campaign>) => void; openTest: () => void }) {
  const heading = channelMeta[draft.channel].title;
  return <div className="editor-body"><section className="editor-card channel-workspace"><div className="card-heading"><div><h2>{heading} Composer</h2><p>{channelMeta[draft.channel].description}</p></div><button className="secondary" onClick={openTest}>Preview and test</button></div><CampaignDetails draft={draft} update={update}/><ChannelFields draft={draft} update={update}/></section></div>;
}

function CampaignDetails({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) {
  return <div className="channel-details"><Field label="Campaign Name"><input value={draft.name} onChange={event => update({ name: event.target.value })}/></Field><button className="tag-button"><Tags size={14}/> Tags</button></div>;
}

function ChannelFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) {
  const channel = draft.channel;
  if (channel === "push") return <PushFields draft={draft} update={update}/>;
  if (channel === "iam") return <InAppFields draft={draft} update={update}/>;
  if (channel === "content") return <ContentCardFields draft={draft} update={update}/>;
  if (channel === "banner") return <BannerFields draft={draft} update={update}/>;
  if (channel === "sms") return <SmsFields draft={draft} update={update}/>;
  if (channel === "webhook") return <WebhookFields draft={draft} update={update}/>;
  if (channel === "whatsapp") return <WhatsAppFields draft={draft} update={update}/>;
  if (channel === "line") return <LineFields draft={draft} update={update}/>;
  if (channel === "multichannel") return <MultichannelFields draft={draft} update={update}/>;
  if (channel === "operator") return <OperatorFields draft={draft} update={update}/>;
  if (channel === "feature") return <FeatureFlagFields draft={draft} update={update}/>;
  return <ApiCampaignFields draft={draft} update={update}/>;
}

function PushFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) { const [platform, setPlatform] = useState("iOS"); return <ChannelPanel title="Push notification" help="Platform-specific payload, buttons, deep links, and delivery options."><div className="segmented"><button className={className(platform === "iOS" && "selected")} onClick={() => setPlatform("iOS")}>iOS</button><button className={className(platform === "Android" && "selected")} onClick={() => setPlatform("Android")}>Android</button><button className={className(platform === "Web" && "selected")} onClick={() => setPlatform("Web")}>Web</button></div><div className="form-grid"><Field label="Notification title"><input value={draft.subject ?? "September offer"} onChange={event => update({ subject: event.target.value })}/></Field><Field label="Deep link"><input defaultValue="myapp://offers/september"/></Field></div><Field label="Message"><textarea value={draft.body ?? "Your 20% offer is ready."} onChange={event => update({ body: event.target.value })}/></Field><div className="form-grid"><Field label="Image URL"><input placeholder="https://..."/></Field><Field label="Sound"><select><option>Default</option><option>None</option></select></Field></div><Toggle title={`Use ${platform} advanced options`} help="Configure interruption level, category, and expiration."/></ChannelPanel>; }
function InAppFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) { const [layout, setLayout] = useState("Modal"); return <ChannelPanel title="Message design" help="Configure the experience rendered by the Braze SDK."><div className="segmented">{["Modal", "Slideup", "Full screen"].map(value => <button key={value} className={className(layout === value && "selected")} onClick={() => setLayout(value)}>{value}</button>)}</div><div className="form-grid"><Field label="Headline"><input value={draft.subject ?? "Welcome to the family"} onChange={event => update({ subject: event.target.value })}/></Field><Field label="Close behavior"><select><option>Dismiss on outside click</option><option>Require button click</option></select></Field></div><Field label="Message"><textarea value={draft.body ?? "Your September offer is ready."} onChange={event => update({ body: event.target.value })}/></Field><div className="form-grid"><Field label="Primary button"><input defaultValue="Shop now"/></Field><Field label="Display trigger"><select><option>On session start</option><option>Custom event</option></select></Field></div><Toggle title="Respect frequency cap" help="Skip users who recently saw an in-app message." checked/></ChannelPanel>; }
function ContentCardFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) { return <ChannelPanel title="Content Card" help="Build a durable card synchronized to the SDK feed."><div className="form-grid"><Field label="Card type"><select><option>Image only</option><option>Captioned image</option><option>Classic</option></select></Field><Field label="Category"><input defaultValue="Promotions"/></Field></div><Field label="Title"><input value={draft.subject ?? "September collection"} onChange={event => update({ subject: event.target.value })}/></Field><Field label="Description"><textarea value={draft.body ?? "Save 20% on featured products."} onChange={event => update({ body: event.target.value })}/></Field><div className="form-grid"><Field label="Image"><input placeholder="Choose from Media Library"/></Field><Field label="Click action"><select><option>Deep link</option><option>URI</option><option>None</option></select></Field></div><Toggle title="Pin this card" help="Keep the card above standard feed content."/><Toggle title="Set expiration" help="Remove the card after a specific date."/></ChannelPanel>; }
function BannerFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) { return <ChannelPanel title="Banner setup" help="Match a registered SDK placement and render its responsive content."><div className="form-grid"><Field label="Placement"><select><option>home_top</option><option>checkout_promo</option></select></Field><Field label="Priority"><select><option>High</option><option>Normal</option><option>Low</option></select></Field></div><Field label="Banner title"><input value={draft.subject ?? "Invite a friend"} onChange={event => update({ subject: event.target.value })}/></Field><Field label="Body"><textarea value={draft.body ?? "Give $10, get $10."} onChange={event => update({ body: event.target.value })}/></Field><div className="banner-mini-preview"><b>{draft.subject ?? "Invite a friend"}</b><span>{draft.body ?? "Give $10, get $10."}</span><button>Learn more</button></div></ChannelPanel>; }
function SmsFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) { const message = draft.body ?? "Use code SEPTEMBER20 for 20% off. Reply STOP to opt out."; return <ChannelPanel title="SMS / MMS / RCS" help="Select an approved sender and subscription group before composing."><div className="segmented"><button className="selected">SMS</button><button>MMS</button><button>RCS</button></div><div className="form-grid"><Field label="Subscription group"><select><option>Promotional messages</option><option>Transactional</option></select></Field><Field label="Sending number"><select><option>+1 415 555 0100</option></select></Field></div><Field label="Message"><textarea value={message} onChange={event => update({ body: event.target.value })}/></Field><small>{message.length} characters · {Math.max(1, Math.ceil(message.length / 160))} segment{message.length > 160 ? "s" : ""}</small><Toggle title="Append STOP instructions" help="Use the workspace opt-out disclosure." checked/></ChannelPanel>; }
function WebhookFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) { return <ChannelPanel title="Webhook request" help="Requests are rendered and simulated locally; no destination URL is contacted."><div className="form-grid"><Field label="Method"><select><option>POST</option><option>PUT</option><option>GET</option></select></Field><Field label="Authentication"><select><option>Bearer token</option><option>Basic</option><option>None</option></select></Field></div><Field label="Webhook URL"><input defaultValue="https://api.example.test/events"/></Field><Field label="Headers"><textarea defaultValue={'Authorization: Bearer {{${api_token}}}\nContent-Type: application/json'}/></Field><Field label="Request body"><textarea value={draft.body ?? '{\n  "user_id": "{{${user_id}}}",\n  "event": "campaign_sent"\n}'} onChange={event => update({ body: event.target.value })}/></Field><button className="secondary">Preview simulated response</button></ChannelPanel>; }
function WhatsAppFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) { return <ChannelPanel title="WhatsApp template" help="Only approved templates can be selected for an outbound campaign."><div className="form-grid"><Field label="Template"><select><option>September offer · Approved</option><option>Order update · Approved</option></select></Field><Field label="Language"><select><option>English (US)</option><option>Chinese (Simplified)</option></select></Field></div><Field label="Header media"><select><option>None</option><option>Image</option></select></Field><Field label="Body parameter preview"><textarea value={draft.body ?? "Hi {{${first_name}}}, your September offer is ready."} onChange={event => update({ body: event.target.value })}/></Field><Field label="Button URL"><input defaultValue="https://example.test/offers"/></Field></ChannelPanel>; }
function LineFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) { return <ChannelPanel title="LINE message" help="Create a message sent through a LINE Official Account."><div className="form-grid"><Field label="Message type"><select><option>Text</option><option>Image</option><option>Flex message</option></select></Field><Field label="Official Account"><select><option>Demo – Thinkingai</option></select></Field></div><Field label="Message content"><textarea value={draft.body ?? "Your September offer is ready."} onChange={event => update({ body: event.target.value })}/></Field><Field label="Action URL"><input defaultValue="https://example.test/offers"/></Field></ChannelPanel>; }
function MultichannelFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) { return <ChannelPanel title="Channel orchestration" help="Define fallback order and message variants for each selected channel."><div className="channel-checks">{["Email", "Push notification", "In-app message", "SMS"].map((name, index) => <label key={name}><input type="checkbox" defaultChecked={index < 2}/>{name}</label>)}</div><Field label="Orchestration rule"><select><option>Send Push, then Email if not opened</option><option>Send all channels at once</option></select></Field><Field label="Campaign message"><textarea value={draft.body ?? "Use your September offer before it expires."} onChange={event => update({ body: event.target.value })}/></Field></ChannelPanel>; }
function OperatorFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) { const [generated, setGenerated] = useState(false); return <ChannelPanel title="Create with Operator" help="The local Operator produces deterministic, editable suggestions."><Field label="Campaign goal"><textarea value={draft.body ?? "Welcome new users and encourage their first purchase."} onChange={event => update({ body: event.target.value })}/></Field><button className="primary" onClick={() => { update({ subject: "Your first order offer", body: "Welcome! Use code WELCOME10 for 10% off your first order." }); setGenerated(true); }}><Sparkles size={15}/> Generate local plan</button>{generated && <div className="subtle-note">Suggested Email + Push journey created. Review and edit each channel before launch.</div>}</ChannelPanel>; }
function FeatureFlagFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) { return <ChannelPanel title="Feature flag experiment" help="Set a stable rollout value and measure exposure against a conversion event."><div className="form-grid"><Field label="Flag key"><input value={draft.subject ?? "new_checkout"} onChange={event => update({ subject: event.target.value })}/></Field><Field label="Rollout"><input type="number" defaultValue="50" min="0" max="100"/></Field></div><Field label="Variant value"><textarea value={draft.body ?? '{"enabled": true}'} onChange={event => update({ body: event.target.value })}/></Field><Field label="Primary conversion"><select><option>Make Purchase</option><option>Start Session</option></select></Field></ChannelPanel>; }
function ApiCampaignFields({ draft, update }: { draft: Campaign; update: (patch: Partial<Campaign>) => void }) { return <ChannelPanel title="API campaign" help="Create an identifier used to associate external sends with campaign analytics."><Field label="Campaign name"><input value={draft.name} onChange={event => update({ name: event.target.value })}/></Field><Field label="API campaign ID"><input value={draft.subject ?? `api_${draft.id}`} onChange={event => update({ subject: event.target.value })}/></Field><Field label="Event mapping"><textarea value={draft.body ?? "External system posts delivery and conversion events using this campaign ID."} onChange={event => update({ body: event.target.value })}/></Field><Toggle title="Allow external attribution" help="Accept locally simulated message and conversion events." checked/></ChannelPanel>; }
function ChannelPanel({ title, help, children }: { title: string; help: string; children: ReactNode }) { return <section className="channel-panel"><h3>{title}</h3><p>{help}</p>{children}</section>; }

function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="field"><span>{label}</span>{children}</label>; }
function Schedule({ draft, update }: { draft: Campaign; update: (p: Partial<Campaign>) => void }) { return <div className="editor-body"><section className="editor-card"><h2>Schedule Delivery</h2><div className="segmented wide"><button className="selected">Scheduled delivery</button><button>Action-based delivery</button><button>API-triggered</button></div><div className="form-grid"><Field label="Send option"><select value={draft.schedule} onChange={e => update({schedule:e.target.value})}><option>One time</option><option>Action-based</option><option>API-triggered</option></select></Field><Field label="Time zone"><select><option>Company time zone (UTC+08:00)</option><option>Recipient local time</option></select></Field><Field label="Start date"><input type="date" defaultValue="2026-09-17"/></Field><Field label="Send time"><input type="time" defaultValue="10:00"/></Field></div><Toggle title="Recurring schedule" help="Repeat this campaign daily, weekly, or monthly."/><Toggle title="Quiet hours" help="Do not send between 9 PM and 8 AM." checked/><Toggle title="Allow users to become re-eligible" help="Users may receive this campaign more than once."/><Field label="Rate limit"><input type="number" defaultValue="5000"/></Field></section></div>; }
function Audience({ draft, update }: { draft: Campaign; update: (p: Partial<Campaign>) => void }) { const [filters, setFilters] = useState([0]); return <div className="editor-body"><section className="editor-card"><h2>Target Audiences</h2><div className="audience-layout"><div><Field label="Target users by segment"><select value={draft.audience} onChange={e => update({audience:e.target.value})}><option>All Users</option><option>Recent Purchasers</option><option>New Users</option></select></Field><div className="filter-box"><b>Additional filters</b>{filters.map((id) => <div className="filter-row" key={id}><select><option>Custom attribute</option><option>Engagement</option></select><select><option>country</option><option>first_name</option></select><select><option>equals US</option><option>is not blank</option></select><button onClick={() => setFilters(f => f.filter(x => x !== id))}><X size={14}/></button></div>)}<button className="secondary small" onClick={() => setFilters(f => [...f, Date.now()])}><Plus size={14}/> Add filter</button></div><Field label="Subscription group"><select><option>Promotional messages</option><option>All subscribed users</option></select></Field></div><div className="audience-meter"><div className="meter-ring"><span>38.4K</span></div><b>Estimated reachable audience</b><small>Users who match current targeting and subscription rules.</small></div></div></section></div>; }
function Conversions({ draft, update }: { draft: Campaign; update: (p: Partial<Campaign>) => void }) { const [events, setEvents] = useState([0]); return <div className="editor-body"><section className="editor-card"><h2>Assign Conversions</h2><p>Track the actions users take after receiving this campaign.</p>{events.map(id => <div className="conversion-row" key={id}><Field label="Conversion event"><select value={draft.conversion} onChange={e => update({conversion:e.target.value})}><option>Make Purchase</option><option>Start Session</option><option>Perform Custom Event</option></select></Field><Field label="Conversion deadline"><select><option>3 days</option><option>7 days</option><option>30 days</option></select></Field>{events.length > 1 && <button className="remove" onClick={() => setEvents(v => v.filter(x => x !== id))}>Remove</button>}</div>)}<button className="secondary" onClick={() => setEvents(v => [...v, Date.now()])}><Plus size={15}/> Add conversion event</button></section></div>; }
function Review({ draft, go }: { draft: Campaign; go: (step: number) => void }) { const sections = [["Campaign details", draft.name, 0], ["Messages", `${channelMeta[draft.channel].title} · Variant 1`, 0], ["Delivery", draft.schedule, 1], ["Audience", draft.audience || "All Users", 2], ["Conversions", draft.conversion || "Make Purchase", 3]]; return <div className="editor-body"><section className="editor-card"><h2>Review Summary</h2><div className="review-grid">{sections.map(([title, value, index]) => <div className="review-item" key={String(title)}><b>{title} <span>✓</span></b><p>{value}</p><button className="secondary small" onClick={() => go(Number(index))}>Edit</button></div>)}</div><div className="launch-panel"><ShieldCheck size={22}/><div><b>Ready to launch</b><p>Configuration is valid. Launch will generate local-only delivery and engagement events.</p></div></div></section></div>; }
function Toggle({ title, help, checked = false }: { title: string; help: string; checked?: boolean }) { const [value, setValue] = useState(checked); return <div className="toggle-row"><div><b>{title}</b><small>{help}</small></div><button className={className("switch", value && "on")} onClick={() => setValue(!value)}><i/></button></div>; }
function MessagePreview({ draft }: { draft: Campaign }) { const title = draft.subject || "Your welcome offer is here"; const body = draft.body || "Thanks for being with us. Use code SEPTEMBER20 to get 20% off."; const channel = draft.channel; return <div className="preview-panel"><div className="preview-head"><span>Preview</span><small>Live preview</small></div><div className="device-stage">{channel === "email" || channel === "multichannel" ? <article className="email-preview"><small>From: Powered by Braze</small><h3>{title}</h3><div className="email-image"/><h2>September Exclusive</h2><p>{body}</p><button>Claim your offer</button></article> : channel === "webhook" ? <pre>POST https://api.example.com/events{`\n\n`}{'{'}{`\n  "user_id": "user_1024",`}{`\n  "event": "campaign_sent"`}{`\n}`}</pre> : <div className="phone"><div className="phone-top">9:41</div>{channel === "iam" ? <div className="iam-card"><div className="email-image"/><h3>{title}</h3><p>{body}</p><button>Shop now</button></div> : channel === "content" ? <div className="content-card"><div className="email-image"/><b>{title}</b><p>{body}</p></div> : channel === "banner" ? <div className="banner-card"><b>{title}</b><p>{body}</p><button>Shop now</button></div> : <div className="notification"><b>{title}</b><p>{body}</p></div>}</div>}</div></div>; }
function LegacyTestModal({ draft, close }: { draft: Campaign; close: () => void }) { const [sent, setSent] = useState(false); return <div className="modal-backdrop"><section className="test-modal"><button className="modal-close" onClick={close}><X size={18}/></button><h2>Preview and test</h2><p>Send a simulated test event to the local activity log. No external service is contacted.</p><Field label="Test user"><input defaultValue="marketing.qa@example.com"/></Field>{sent ? <div className="test-success"><ShieldCheck size={18}/><span>Test event created for {channelMeta[draft.channel].title}.</span></div> : <button className="primary" onClick={() => setSent(true)}><Send size={15}/> Send test</button>}</section></div>; }

function TestModal({ draft, close }: { draft: Campaign; close: () => void }) {
  const [recipient, setRecipient] = useState("marketing.qa@example.com");
  const [state, setState] = useState<"idle" | "sending" | "sent" | "error">("idle");
  const send = async () => {
    setState("sending");
    const response = await fetch(`/api/campaigns/${draft.id}/test`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ recipient }) });
    setState(response.ok ? "sent" : "error");
  };
  return <div className="modal-backdrop"><section className="test-modal"><button className="modal-close" onClick={close}><X size={18}/></button><h2>Preview and test</h2><p>Write a test delivery event to the local SQLite activity log. No external service is contacted.</p><Field label="Test user"><input value={recipient} onChange={event => setRecipient(event.target.value)}/></Field>{state === "sent" ? <div className="test-success"><ShieldCheck size={18}/><span>Test delivery recorded for {recipient}.</span></div> : <><button className="primary" disabled={state === "sending"} onClick={send}><Send size={15}/>{state === "sending" ? "Sending…" : "Send test"}</button>{state === "error" && <p className="form-error">The local test event could not be created.</p>}</>}</section></div>;
}

function CollectionPage({ title, page, notify, openPage }: { title: string; page: string; notify: (x: string) => void; openPage: (x: string) => void }) { const [rows, setRows] = useState([`${title} default`, `${title} lifecycle`, `${title} production`]); const [query, setQuery] = useState(""); const visible = rows.filter(x => x.toLowerCase().includes(query.toLowerCase())); const kind = page.includes("analytics") || title.includes("Report") || title.includes("Performance") ? "report" : page.includes("settings") || page === "settings" ? "settings" : "resource";
  if (kind === "report") return <ReportPage title={title} notify={notify}/>;
  return <section className="page-content"><div className="page-heading"><div><div className="title-line"><h1>{title}</h1><span className="access-pill">Limited access</span></div><p>{collectionDescription(title)}</p></div><div className="heading-actions"><button className="secondary" onClick={() => notify("Export prepared in the local activity log.")}>Export</button><button className="primary" onClick={() => setRows(r => [`${title} ${r.length + 1}`, ...r])}><Plus size={16}/> Create {singular(title)}</button></div></div>{page === "segments" && <SegmentBuilder notify={notify}/>} {page === "landing-pages" && <LandingPreview/>} {page === "messaging-diagnostics" && <Diagnostics/>} {page === "search-users" && <UserSearch/>} {page === "catalogs" && <CatalogPreview/>} {page === "approval-workflow" && <ApprovalSettings notify={notify}/>} {kind === "settings" && <SettingsPanel title={title} notify={notify}/>}<div className="list-toolbar"><div className="filter-search"><Search size={15}/><input placeholder={`Search ${title.toLowerCase()}`} value={query} onChange={e => setQuery(e.target.value)}/></div><button className="secondary"><Filter size={15}/> Filters</button><button className="secondary"><Grid2X2 size={15}/> Columns</button></div><div className="generic-list">{visible.map((row, i) => <div className="generic-row" key={row}><span className="resource-avatar">{title[0]}</span><div><b>{row}</b><small>{i === 0 ? "Active · Updated just now" : "Draft · Updated Sep 15, 2026"}</small></div><span className="row-detail">{kind === "settings" ? "Workspace default" : i % 2 ? "Lifecycle Marketing" : "Demo – Thinkingai"}</span><button className="icon-button" onClick={() => notify(`${row} was opened in the local demo.`)}><MoreHorizontal size={18}/></button></div>)}</div>{page === "content-calendar" && <CalendarGrid openPage={openPage}/>}</section>; }

function collectionDescription(title: string) { const map: Record<string,string> = { "Segments": "Split your audience into segments to target a specific list of users.", "Feature Flags": "Remotely turn native functionality on or off for a selection of users.", "Landing Pages": "Build standalone web pages that drive conversions and grow your subscriber list.", "Media Library": "Store and reuse images, video, and files across messages.", "Message Activity Log": "Review the local message events created by simulated campaign delivery.", "Custom Attributes": "Manage the custom attributes collected from your users.", "Technology Partners": "Connect Braze to the technologies your team uses." }; return map[title] || `Manage ${title.toLowerCase()} for this workspace.`; }
function singular(title: string) { return title.endsWith("s") ? title.slice(0,-1) : title; }
function ReportPage({ title, notify }: { title:string; notify:(x:string)=>void }) { const [range, setRange] = useState("Last 30 days"); return <section className="page-content"><div className="page-heading"><div><h1>{title}</h1><p>Analyze locally generated delivery and engagement events.</p></div><div className="heading-actions"><select className="date-select" value={range} onChange={e=>setRange(e.target.value)}><option>Last 7 days</option><option>Last 30 days</option><option>Last 90 days</option></select><button className="primary" onClick={()=>notify("Report definition saved.")}><Plus size={15}/> Create report</button></div></div><div className="metric-grid">{[["Delivered", "38,420", "+12.4%"],["Engagement", "4,972", "+8.1%"],["Conversions", "1,018", "+5.2%"],["Unsubscribes", "63", "-1.4%"]].map(([label,value,change])=><div className="metric" key={label}><small>{label}</small><b>{value}</b><span>{change}</span></div>)}</div><section className="chart-card"><div><h2>Campaign performance</h2><p>{range} · modeled local event data</p></div><div className="bar-chart">{[34,51,42,72,59,84,68,92,75,100,81,87].map((h,i)=><span key={i} style={{height:`${h}%`}}/>)}</div></section></section>; }
function CanvasPage({ notify }: { notify: (x:string)=>void }) { const [nodes,setNodes] = useState(["Audience entry", "Delay · 1 day", "Email message"]); const [selected,setSelected]=useState(2); return <section className="canvas-page"><div className="page-heading"><div><h1>Canvas</h1><p>Build and simulate a customer journey.</p></div><div className="heading-actions"><button className="secondary" onClick={()=>notify("Canvas saved.")}>Save Draft</button><button className="primary" onClick={()=>notify("Canvas launched. 124 local users entered the journey.")}>Launch Canvas</button></div></div><div className="canvas-shell"><aside><h3>Steps</h3>{["Audience Paths", "Message", "Delay", "Action Paths", "Update User"].map(x=><button key={x} onClick={()=>setNodes(n=>[...n,x])}><Plus size={14}/>{x}</button>)}<hr/><h3>Inspector</h3><p>{nodes[selected] || "Select a node"}</p><label>Step name<input value={nodes[selected] || ""} onChange={e=>setNodes(n=>n.map((x,i)=>i===selected?e.target.value:x))}/></label></aside><div className="journey-canvas"><div className="zoom-control">− &nbsp; 100% &nbsp; +</div>{nodes.map((node,i)=><button key={`${node}-${i}`} className={className("journey-node", selected===i&&"selected")} style={{left:`${110+i*205}px`,top:`${210+(i%2)*84}px`}} onClick={()=>setSelected(i)}>{i>0&&<i/>}{i===0?<Users size={18}/>:i===1?<CalendarDays size={18}/>:<Mail size={18}/>}<span>{node}</span></button>)}</div></div></section>; }
function GettingStarted({ openPage }: { openPage:(p:string)=>void }) { const [done,setDone]=useState([false,false,false]); const tasks=[["Get to know the Braze dashboard","Explore key features and create your first content.","campaigns"],["Send your first live email campaign","Create a campaign and send a simulated test.","campaigns"],["Scale your strategy","Build a segment and an automated journey.","segments"]]; return <section className="page-content getting"><div className="page-heading"><div><h1>Your getting started checklist</h1><p>Explore Braze features in the demo workspace, then switch into the live workspace to launch a campaign.</p></div></div><section className="checklist"><div className="progress-line"><span style={{width:`${done.filter(Boolean).length/3*100}%`}}/></div><b>{done.filter(Boolean).length} of 3 milestones completed</b>{tasks.map(([title,desc,target],i)=><div className="check-item" key={title}><button className={className("task-check",done[i]&&"done")} onClick={()=>setDone(d=>d.map((x,index)=>index===i?!x:x))}>{done[i]&&"✓"}</button><div><h3>{title}</h3><p>{desc}</p></div><button className="secondary" onClick={()=>openPage(target)}>Begin</button></div>)}</section></section>; }
function Performance({ campaigns }: { campaigns:Campaign[] }) { return <LiveReportPage title="Performance Overview" />; }
function DemoLab({ notify }: { notify:(x:string)=>void }) { return <section className="page-content"><div className="page-heading"><div><h1>Demo Lab</h1><p>Control deterministic local delivery data without changing the dashboard experience.</p></div></div><div className="lab-grid">{[["Advance simulated time","Move scheduled work forward by one day"],["Generate delivery receipts","Create success, bounce, click and impression events"],["Inject a failure","Create a token, template or rate-limit error"],["Reset sample data","Restore the deterministic workspace seed"]].map(([title,desc])=><button key={title} className="lab-action" onClick={()=>notify(`${title} completed in the local simulation.`)}><Zap size={20}/><b>{title}</b><small>{desc}</small></button>)}</div></section>; }
function SegmentBuilder({ notify }:{notify:(m:string)=>void}) { return <section className="builder-inline"><h2>Segment builder</h2><div className="filter-row"><select><option>Custom attribute</option></select><select><option>country</option></select><select><option>equals US</option></select></div><button className="secondary small" onClick={()=>notify("Segment condition saved.")}><Plus size={14}/> Add filter</button></section>; }
function LandingPreview(){return <section className="landing-preview"><div><span>THE SEPTEMBER EDIT</span><h2>Twenty percent off, before the month ends.</h2><p>A local landing page preview with editable content blocks.</p><button>Claim your offer</button></div></section>; }
function Diagnostics(){return <section className="diagnostics"><ShieldCheck size={20}/><div><b>No delivery issues in the last 24 hours</b><p>Simulated events are checked for configuration, eligibility and delivery errors.</p></div></section>; }
function UserSearch(){return <section className="user-search"><Search size={17}/><input placeholder="Search by external ID, email, or phone number"/><button className="primary">Search</button></section>; }
function CatalogPreview(){return <section className="catalog-preview"><div className="catalog-image"/><div><b>Featured collection</b><p>SKU-0926 · 20 products</p><button className="secondary small">View items</button></div></section>; }
function ApprovalSettings({notify}:{notify:(m:string)=>void}) { return <section className="builder-inline"><h2>Campaign approval workflow</h2><Toggle title="Require approval before launch" help="Drafts require a reviewer before they can be launched." checked/><button className="primary" onClick={()=>notify("Approval workflow saved.")}>Save changes</button></section>; }
function SettingsPanel({title,notify}:{title:string;notify:(m:string)=>void}) { return <section className="settings-panel"><h2>{title}</h2><Toggle title="Use workspace default" help="Apply this configuration to new campaigns." checked/><Toggle title="Notify workspace admins" help="Create a local notification when this setting changes."/><button className="primary small" onClick={()=>notify(`${title} saved.`)}>Save changes</button></section>; }
function CalendarGrid({openPage}:{openPage:(x:string)=>void}) { return <section className="calendar-grid"><div className="calendar-head">September 2026 <button onClick={()=>openPage("campaigns")}>View campaigns</button></div>{Array.from({length:28},(_,i)=><div key={i}><small>{i+1}</small>{[4,12,17,24].includes(i)&&<span>Campaign</span>}</div>)}</section>; }
function UserSearchEmpty(){ return null; }

type Overview = { delivered: number; opened: number; clicked: number; suppressed: number; unreachable: number; series: { date: string; delivered: number }[] };

function LiveReportPage({ title }: { title: string }) {
  const [range, setRange] = useState("30");
  const [overview, setOverview] = useState<Overview | null>(null);
  useEffect(() => { void fetch(`/api/reports/overview?days=${range}`).then(response => response.json()).then(setOverview); }, [range]);
  const delivered = overview?.delivered ?? 0; const opened = overview?.opened ?? 0; const clicked = overview?.clicked ?? 0;
  const max = Math.max(...(overview?.series.map(point => point.delivered) ?? [1]), 1);
  return <section className="page-content"><div className="page-heading"><div><h1>{title}</h1><p>Metrics are calculated from local execution runs and message events.</p></div><select className="date-select" value={range} onChange={event => setRange(event.target.value)}><option value="7">Last 7 days</option><option value="30">Last 30 days</option><option value="90">Last 90 days</option></select></div><div className="metric-grid">{[["Delivered", delivered], ["Opened", opened], ["Clicked", clicked], ["Suppressed", overview?.suppressed ?? 0], ["Unreachable", overview?.unreachable ?? 0]].map(([label, value]) => <div className="metric" key={String(label)}><small>{label}</small><b>{Number(value).toLocaleString()}</b><span>{delivered ? `${Math.round(Number(value) / delivered * 100)}% of delivered` : "No executions yet"}</span></div>)}</div><section className="chart-card"><div><h2>Campaign delivery runs</h2><p>Each bar is a completed local execution snapshot.</p></div><div className="bar-chart" aria-label="Delivery run chart">{overview?.series.length ? overview.series.map((point, index) => <span key={`${point.date}-${index}`} title={`${point.delivered} delivered`} style={{ height: `${Math.max(8, point.delivered / max * 100)}%` }}/>) : <p className="empty-inline">Launch a campaign or send a test to create report data.</p>}</div></section></section>;
}

function LiveDemoLab({ notify }: { notify: (message: string) => void }) {
  const [working, setWorking] = useState<string | null>(null);
  const actions = [["advance", "Advance simulated time", "Move local schedules forward by one day"], ["receipts", "Generate delivery receipts", "Generate receipts from completed executions"], ["failure", "Inject a failure", "Write a rate-limit failure into the activity log"], ["reset", "Reset sample data", "Restore campaigns, resources, users and local events"]] as const;
  const run = async (action: string) => { setWorking(action); const response = await fetch("/api/demo", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action }) }); const result = await response.json(); setWorking(null); notify(result.message ?? "Demo action completed."); };
  return <section className="page-content"><div className="page-heading"><div><h1>Demo Lab</h1><p>Control the same SQLite data that powers campaign execution, activity, and reports.</p></div></div><div className="lab-grid">{actions.map(([action, title, description]) => <button key={action} className="lab-action" disabled={working !== null} onClick={() => void run(action)}><Zap size={20}/><b>{working === action ? "Working…" : title}</b><small>{description}</small></button>)}</div></section>;
}

function ActivityLogPage() {
  const [events, setEvents] = useState<Record<string, unknown>[]>([]);
  useEffect(() => { void fetch("/api/activity").then(response => response.json()).then(result => setEvents(result.data)); }, []);
  return <section className="page-content"><div className="page-heading"><div><h1>Message Activity Log</h1><p>Local test, delivery, engagement, suppression and failure events.</p></div></div><div className="table-wrap"><table><thead><tr><th>Event</th><th>Campaign</th><th>Channel</th><th>User</th><th>Timestamp</th></tr></thead><tbody>{events.length ? events.map(event => <tr key={String(event.id)}><td><span className="status active">{String(event.event_type)}</span></td><td>{String(event.campaign_name ?? event.campaign_id)}</td><td>{String(event.channel)}</td><td>{String(event.user_id)}</td><td>{new Date(String(event.created_at)).toLocaleString()}</td></tr>) : <tr><td colSpan={5}>No message events have been recorded.</td></tr>}</tbody></table></div></section>;
}

type JourneyNode = { id: string; label: string; kind: "entry" | "delay" | "message" | "branch" | "update"; x: number; y: number };
type JourneyState = { nodes: JourneyNode[]; edges: [string, string][] };

function LiveCanvas({ notify }: { notify: (message: string) => void }) {
  const initial: JourneyState = { nodes: [{ id: "entry", label: "Audience entry", kind: "entry", x: 110, y: 190 }, { id: "delay", label: "Delay · 1 day", kind: "delay", x: 360, y: 190 }, { id: "email", label: "Email message", kind: "message", x: 610, y: 190 }], edges: [["entry", "delay"], ["delay", "email"]] };
  const [history, setHistory] = useState<JourneyState[]>([initial]); const [cursor, setCursor] = useState(0);
  const [selected, setSelected] = useState("email"); const [zoom, setZoom] = useState(1); const [linkFrom, setLinkFrom] = useState<string | null>(null); const [execution, setExecution] = useState<string[]>([]);
  const state = history[cursor];
  const commit = (next: JourneyState) => { setHistory(previous => [...previous.slice(0, cursor + 1), next]); setCursor(value => value + 1); };
  const add = (kind: JourneyNode["kind"]) => { const label = kind === "message" ? "Email message" : kind === "delay" ? "Delay · 1 day" : kind === "branch" ? "Action path" : kind === "update" ? "Update user" : "Audience entry"; const id = `${kind}_${Date.now()}`; commit({ ...state, nodes: [...state.nodes, { id, label, kind, x: 180 + state.nodes.length * 48, y: 320, } ] }); setSelected(id); };
  const move = (id: string, event: React.PointerEvent<HTMLButtonElement>) => {
    const element = event.currentTarget;
    const start = { x: event.clientX, y: event.clientY, left: Number(element.dataset.x), top: Number(element.dataset.y) };
    let latest = { x: start.left, y: start.top };
    element.setPointerCapture(event.pointerId);
    const onMove = (pointer: PointerEvent) => {
      const x = Math.max(20, start.left + (pointer.clientX - start.x) / zoom);
      const y = Math.max(20, start.top + (pointer.clientY - start.y) / zoom);
      latest = { x, y };
      setHistory(previous => previous.map((snapshot, index) => index === cursor ? { ...snapshot, nodes: snapshot.nodes.map(node => node.id === id ? { ...node, x, y } : node) } : snapshot));
    };
    const onUp = () => {
      element.removeEventListener("pointermove", onMove); element.removeEventListener("pointerup", onUp);
      setHistory(previous => {
        const current = previous[cursor];
        const next = { ...current, nodes: current.nodes.map(node => node.id === id ? { ...node, ...latest } : node) };
        return [...previous.slice(0, cursor + 1), next];
      });
      setCursor(value => value + 1);
    };
    element.addEventListener("pointermove", onMove); element.addEventListener("pointerup", onUp);
  };
  const connect = (id: string) => { if (!linkFrom) { setLinkFrom(id); return; } if (linkFrom !== id && !state.edges.some(edge => edge[0] === linkFrom && edge[1] === id)) commit({ ...state, edges: [...state.edges, [linkFrom, id]] }); setLinkFrom(null); };
  const rename = (label: string) => commit({ ...state, nodes: state.nodes.map(node => node.id === selected ? { ...node, label } : node) });
  const remove = () => { commit({ nodes: state.nodes.filter(node => node.id !== selected), edges: state.edges.filter(edge => !edge.includes(selected)) }); setSelected(""); };
  const copy = () => { const node = state.nodes.find(item => item.id === selected); if (!node) return; const id = `${node.kind}_${Date.now()}`; commit({ ...state, nodes: [...state.nodes, { ...node, id, label: `${node.label} copy`, x: node.x + 36, y: node.y + 48 }] }); setSelected(id); };
  const save = async () => { await fetch("/api/resources/canvas", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name: "Local canvas draft", description: "Saved visual journey graph", data: state }) }); notify("Canvas graph saved to local SQLite."); };
  const launch = () => { if (state.nodes.length < 2 || state.edges.length < state.nodes.length - 1) { notify("Canvas needs connected steps before it can launch."); return; } setExecution(state.nodes.map(node => `${node.label}: completed`)); notify("Canvas execution simulated for the current journey graph."); };
  const selectedNode = state.nodes.find(node => node.id === selected);
  return <section className="canvas-page"><div className="page-heading"><div><h1>Canvas</h1><p>Build, validate, persist, and simulate a local customer journey.</p></div><div className="heading-actions"><button className="secondary" disabled={cursor === 0} onClick={() => setCursor(value => value - 1)}>Undo</button><button className="secondary" disabled={cursor === history.length - 1} onClick={() => setCursor(value => value + 1)}>Redo</button><button className="secondary" onClick={() => void save()}>Save Draft</button><button className="primary" onClick={launch}>Launch Canvas</button></div></div><div className="canvas-shell live-canvas-shell"><aside><h3>Steps</h3>{(["entry", "message", "delay", "branch", "update"] as JourneyNode["kind"][]).map(kind => <button key={kind} onClick={() => add(kind)}><Plus size={14}/>{kind === "entry" ? "Audience Paths" : kind === "message" ? "Message" : kind === "delay" ? "Delay" : kind === "branch" ? "Action Paths" : "Update User"}</button>)}<hr/><h3>Inspector</h3>{selectedNode ? <><label>Step name<input value={selectedNode.label} onChange={event => rename(event.target.value)}/></label><button className="secondary small" onClick={copy}>Copy step</button><button className="text-button danger" onClick={remove}>Delete step</button></> : <p>Select a node</p>}<hr/><h3>Execution</h3>{execution.length ? execution.map(item => <small className="execution-item" key={item}>✓ {item}</small>) : <small>Launch to inspect the local path.</small>}</aside><div className="journey-canvas live-journey-canvas"><div className="zoom-control"><button onClick={() => setZoom(value => Math.max(.6, value - .1))}>−</button><span>{Math.round(zoom * 100)}%</span><button onClick={() => setZoom(value => Math.min(1.5, value + .1))}>+</button></div><div className="canvas-world" style={{ transform: `scale(${zoom})` }}>{state.edges.map(([from, to]) => { const start = state.nodes.find(node => node.id === from); const end = state.nodes.find(node => node.id === to); return start && end ? <svg className="canvas-edge" key={`${from}-${to}`}><line x1={start.x + 160} y1={start.y + 36} x2={end.x} y2={end.y + 36}/></svg> : null; })}{state.nodes.map(node => <button key={node.id} data-x={node.x} data-y={node.y} className={className("journey-node", selected === node.id && "selected", linkFrom === node.id && "link-source")} style={{ left: node.x, top: node.y }} onPointerDown={event => move(node.id, event)} onClick={() => { setSelected(node.id); connect(node.id); }}><span className="node-grip">⋮⋮</span>{node.kind === "entry" ? <Users size={18}/> : node.kind === "delay" ? <CalendarDays size={18}/> : node.kind === "branch" ? <MousePointerClick size={18}/> : node.kind === "update" ? <Activity size={18}/> : <Mail size={18}/>}<span>{node.label}</span></button>)}</div>{linkFrom && <div className="connect-hint">Select another node to create a connection.</div>}</div></div></section>;
}

function ModuleWorkspace({ title, page, notify, openPage }: { title: string; page: string; notify: (message: string) => void; openPage: (page: string) => void }) {
  const domain = ["segments", "segment-extensions", "global-control-group", "suppression-lists", "subscription-group-management", "email-preference-centers", "search-users", "manage-audience", "import-users", "locations"].includes(page) ? "audience" : ["media-library", "banner-templates", "canvas-templates", "content-blocks", "email-link-templates", "email-templates", "in-app-message-templates", "webhook-templates", "promotion-codes", "catalogs", "brand-guidelines"].includes(page) ? "content" : ["technology-partners", "currents", "data-sharing", "solutions-partners"].includes(page) ? "integrations" : ["custom-attributes", "custom-events", "products", "cloud-data-ingestion", "data-transformation"].includes(page) ? "data" : page.includes("settings") || ["app-settings", "apis-and-identifiers", "internal-groups", "exports-log", "tag-management", "email-preferences", "frequency-capping-rules", "push-settings", "approval-workflow", "localization-settings", "banner-placements", "messaging-rate-limits", "billing", "user-management"].includes(page) ? "settings" : "messaging";
  return <section className="page-content module-workspace"><div className="page-heading"><div><div className="title-line"><h1>{title}</h1><span className="access-pill">Limited access</span></div><p>{moduleDescription(domain, title)}</p></div><div className="heading-actions"><button className="secondary" onClick={() => notify(`${title} export prepared from local SQLite.`)}>Export</button><button className="primary" onClick={() => void document.getElementById("resource-name")?.focus()}><Plus size={16}/> Create {singular(title)}</button></div></div><DomainConfiguration domain={domain} page={page} openPage={openPage} notify={notify}/><PersistentResourceList page={page} title={title} notify={notify}/></section>;
}

function moduleDescription(domain: string, title: string) { const copy: Record<string, string> = { audience: "Define users, subscriptions, eligibility, and audience controls used by local campaign execution.", content: "Manage reusable message content, templates, media, catalogs, and promotion data.", integrations: "Configure local representations of partner connections, data sharing, and delivery logs.", data: "Define the data schema and ingestion inputs that power targeting and personalization.", settings: "Configure workspace defaults, governance, channel settings, and local access controls.", messaging: "Configure message assets, entry rules, and delivery diagnostics." }; return copy[domain] ?? `Manage ${title.toLowerCase()} for this workspace.`; }

function DomainConfiguration({ domain, page, openPage, notify }: { domain: string; page: string; openPage: (page: string) => void; notify: (message: string) => void }) {
  if (page === "segments") return <section className="domain-config"><h2>Segment builder</h2><div className="filter-row"><select><option>Custom attribute</option><option>Event</option><option>Subscription</option></select><select><option>country</option><option>lifecycle</option></select><select><option>equals US</option><option>equals Recent Purchasers</option></select></div><div className="audience-meter"><div className="meter-ring"><span>1,000</span></div><b>Local users available for estimates</b><button className="secondary small" onClick={() => notify("Segment condition saved to the local workspace.")}>Estimate audience</button></div></section>;
  if (domain === "content") return <section className="domain-config content-config"><div className="content-thumbnail"/><div><h2>{page === "catalogs" ? "Catalog schema" : "Reusable content"}</h2><p>{page === "catalogs" ? "sku, name, price, image, inventory and custom product fields are available to local Liquid previews." : "Resources created here can be selected by the matching campaign composer."}</p><button className="secondary small" onClick={() => openPage(page === "catalogs" ? "campaigns" : "email-templates")}>Open related workspace</button></div></section>;
  if (domain === "integrations") return <section className="domain-config integration-config"><ShieldCheck size={22}/><div><h2>Connection status</h2><p>Local simulation is enabled. Connection tests render a deterministic success or failure result and do not call external systems.</p></div><button className="secondary small" onClick={() => notify("Local connection test succeeded. No external request was sent.")}>Test connection</button></section>;
  if (domain === "data") return <section className="domain-config"><h2>Data definition</h2><div className="schema-fields"><span>first_name <i>string</i></span><span>country <i>string</i></span><span>language <i>string</i></span><span>Make Purchase <i>event</i></span></div></section>;
  if (domain === "settings") return <section className="domain-config"><h2>Workspace default</h2><Toggle title="Use workspace default" help="Apply this setting to new local resources and campaigns." checked/><button className="primary small" onClick={() => notify(`${page} saved in local SQLite audit log.`)}>Save changes</button></section>;
  return <section className="domain-config"><h2>Workspace configuration</h2><div className="form-grid"><Field label="Status"><select><option>Active</option><option>Draft</option></select></Field><Field label="Owner"><select><option>Lifecycle Marketing</option><option>Growth</option></select></Field></div><button className="secondary small" onClick={() => notify("Messaging configuration saved.")}>Save configuration</button></section>;
}

function PersistentResourceList({ page, title, notify }: { page: string; title: string; notify: (message: string) => void }) {
  const [rows, setRows] = useState<{ id: string; name: string; status: string; description: string; updatedAt: string }[]>([]); const [query, setQuery] = useState(""); const [creating, setCreating] = useState(false); const [name, setName] = useState("");
  const load = async () => { const response = await fetch(`/api/resources/${page}?q=${encodeURIComponent(query)}`); if (response.ok) { const result = await response.json(); setRows(result.data); } };
  useEffect(() => { void load(); }, [page, query]);
  const create = async () => { if (!name.trim()) return; const response = await fetch(`/api/resources/${page}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name, description: `Local ${title.toLowerCase()} resource` }) }); if (response.ok) { setName(""); setCreating(false); await load(); notify(`${title} resource saved to local SQLite.`); } };
  return <section className="resource-workspace"><div className="list-toolbar"><div className="filter-search"><Search size={15}/><input placeholder={`Search ${title.toLowerCase()}`} value={query} onChange={event => setQuery(event.target.value)}/></div><button className="secondary" onClick={() => setCreating(value => !value)}><Plus size={15}/> Create</button></div>{creating && <div className="resource-create"><input id="resource-name" autoFocus placeholder={`Name this ${singular(title).toLowerCase()}`} value={name} onChange={event => setName(event.target.value)} onKeyDown={event => { if (event.key === "Enter") void create(); }}/><button className="primary small" onClick={() => void create()}>Save</button></div>}<div className="resource-cards">{rows.length ? rows.map(row => <article key={row.id}><div className="resource-avatar">{row.name[0]}</div><div><b>{row.name}</b><p>{row.description}</p><small>{row.status} · {new Date(row.updatedAt).toLocaleString()}</small></div><button className="icon-button" onClick={() => notify(`${row.name} opened in its local workspace.`)}><MoreHorizontal size={18}/></button></article>) : <div className="empty-inline">No {title.toLowerCase()} resources found.</div>}</div></section>;
}

type Catalog = { id: string; name: string; status: string; description: string; data: { fields?: string[] }; itemCount: number };
type CatalogItem = { id: string; name: string; fields: Record<string, unknown>; updatedAt: string };

function CatalogWorkspace({ notify }: { notify: (message: string) => void }) {
  const [catalogs, setCatalogs] = useState<Catalog[]>([]); const [selectedId, setSelectedId] = useState(""); const [items, setItems] = useState<CatalogItem[]>([]); const [query, setQuery] = useState(""); const [newCatalog, setNewCatalog] = useState(""); const [itemEditor, setItemEditor] = useState<CatalogItem | null>(null);
  const selected = catalogs.find(catalog => catalog.id === selectedId) ?? catalogs[0];
  const loadCatalogs = async () => { const response = await fetch("/api/catalogs"); if (response.ok) { const result = await response.json(); setCatalogs(result.data); setSelectedId(current => current || result.data[0]?.id || ""); } };
  const loadItems = async () => { if (!selected?.id) return; const response = await fetch(`/api/catalogs/${selected.id}/items?q=${encodeURIComponent(query)}`); if (response.ok) { const result = await response.json(); setItems(result.data); } };
  useEffect(() => { void loadCatalogs(); }, []); useEffect(() => { void loadItems(); }, [selected?.id, query]);
  const createCatalog = async () => { if (!newCatalog.trim()) return; const response = await fetch("/api/catalogs", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name: newCatalog }) }); if (response.ok) { const catalog = await response.json(); setNewCatalog(""); await loadCatalogs(); setSelectedId(catalog.id); notify("Catalog created in local SQLite."); } };
  const saveItem = async (item: CatalogItem) => { if (!selected) return; const response = await fetch(`/api/catalogs/${selected.id}/items${items.some(row => row.id === item.id) ? `/${item.id}` : ""}`, { method: items.some(row => row.id === item.id) ? "PATCH" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(item) }); if (response.ok) { setItemEditor(null); await loadItems(); await loadCatalogs(); notify("Catalog item saved."); } };
  const removeItem = async (id: string) => { if (!selected) return; await fetch(`/api/catalogs/${selected.id}/items/${id}`, { method: "DELETE" }); await loadItems(); await loadCatalogs(); notify("Catalog item deleted."); };
  return <section className="page-content catalog-workspace"><div className="page-heading"><div><div className="title-line"><h1>Catalogs</h1><span className="access-pill">Limited access</span></div><p>Manage non-user data used for Liquid personalization, recommendations, and promotions.</p></div><div className="heading-actions"><input className="new-catalog" placeholder="New catalog name" value={newCatalog} onChange={event => setNewCatalog(event.target.value)} onKeyDown={event => { if (event.key === "Enter") void createCatalog(); }}/><button className="primary" onClick={() => void createCatalog()}><Plus size={16}/> Create catalog</button></div></div><div className="catalog-layout"><aside className="catalog-list"><h2>Catalogs</h2>{catalogs.map(catalog => <button key={catalog.id} className={className(selected?.id === catalog.id && "selected")} onClick={() => setSelectedId(catalog.id)}><span><b>{catalog.name}</b><small>{catalog.itemCount} items · {catalog.status}</small></span><ChevronRight size={15}/></button>)}</aside>{selected && <main className="catalog-detail"><div className="catalog-detail-head"><div><h2>{selected.name}</h2><p>{selected.description}</p></div><button className="secondary" onClick={() => notify("Catalog export prepared locally.")}>Export items</button></div><section className="catalog-schema"><div><b>Fields</b><p>Item ID and Name are required. These fields are exposed to local Liquid previews.</p></div><div className="schema-fields">{(selected.data.fields ?? ["sku", "name", "price", "image"]).map(field => <span key={field}>{field}<i>{field === "price" ? "number" : "string"}</i></span>)}</div></section><div className="list-toolbar"><div className="filter-search"><Search size={15}/><input placeholder="Search items" value={query} onChange={event => setQuery(event.target.value)}/></div><button className="primary small" onClick={() => setItemEditor({ id: `item_${Date.now()}`, name: "", fields: {}, updatedAt: new Date().toISOString() })}><Plus size={15}/> Add item</button></div><div className="table-wrap"><table><thead><tr><th>Item ID</th><th>Name</th><th>Price</th><th>Category</th><th>Inventory</th><th></th></tr></thead><tbody>{items.map(item => <tr key={item.id}><td>{item.id}</td><td><button className="link-button" onClick={() => setItemEditor(item)}>{item.name}</button></td><td>{String(item.fields.price ?? "—")}</td><td>{String(item.fields.category ?? "—")}</td><td>{String(item.fields.inventory ?? "—")}</td><td><button className="icon-button" onClick={() => void removeItem(item.id)} title="Delete item"><X size={16}/></button></td></tr>)}{!items.length && <tr><td colSpan={6}>No items match this search.</td></tr>}</tbody></table></div></main>}</div>{itemEditor && <CatalogItemModal item={itemEditor} close={() => setItemEditor(null)} save={saveItem}/>}</section>;
}

function CatalogItemModal({ item, close, save }: { item: CatalogItem; close: () => void; save: (item: CatalogItem) => Promise<void> }) {
  const [draft, setDraft] = useState(item); const [json, setJson] = useState(JSON.stringify(item.fields, null, 2)); const [error, setError] = useState("");
  const submit = async () => { try { const fields = JSON.parse(json) as Record<string, unknown>; if (!draft.id || !draft.name) { setError("Item ID and Name are required."); return; } await save({ ...draft, fields }); } catch { setError("Fields must be valid JSON."); } };
  return <div className="modal-backdrop"><section className="test-modal catalog-item-modal"><button className="modal-close" onClick={close}><X size={18}/></button><h2>{item.name ? "Edit catalog item" : "Add catalog item"}</h2><Field label="Item ID"><input value={draft.id} onChange={event => setDraft({ ...draft, id: event.target.value })}/></Field><Field label="Name"><input value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })}/></Field><Field label="Fields (JSON)"><textarea value={json} onChange={event => setJson(event.target.value)}/></Field>{error && <p className="form-error">{error}</p>}<button className="primary" onClick={() => void submit()}>Save item</button></section></div>;
}
